wwv_flow_imp_page.create_page_process(
 p_id=>wwv_flow_imp.id(24321147001903121203)
,p_process_sequence=>10
,p_process_point=>'ON_DEMAND'
,p_process_type=>'NATIVE_PLSQL'
,p_process_name=>'Expand'
,p_static_id=>'expand'
,p_process_sql_clob=>wwv_flow_string.join(wwv_flow_t_varchar2(
'DECLARE data clob;',
'    ids sys.dbms_sql.varchar2a :=  APEX_APPLICATION.G_F01;',
'    graph VARCHAR2(100) := ''EBA_SAMPLE_GRAPH'';',
'    hops NUMBER := APEX_APPLICATION.G_x01;',
'    n NUMBER := hops - 1;',
'    id_strings VARCHAR2(32767) := '' ('';',
'    query VARCHAR2(1000);',
'',
'BEGIN',
'    for i in ids.FIRST..ids.LAST LOOP',
'        IF i = ids.COUNT THEN',
'            id_strings := id_strings || apex_exec.enquote_literal(ids(i)) || '') '';    ',
'        ELSE     ',
'            id_strings := id_strings || apex_exec.enquote_literal(ids(i)) || '', '';',
'        END IF;',
'    END LOOP;',
'    IF hops > 1 THEN',
'        query :=',
'            ''SELECT E1 FROM MATCH ANY (x) ->{,''',
'            || n',
'            || ''} (y) ON ''',
'            || graph',
'            || '', MATCH (y) -[e1]-> () ON ''',
'            || graph',
'            || '' WHERE id(x) IN ''',
'            || id_strings;',
'    ELSE',
'        query :=',
'            ''SELECT E1 FROM MATCH (x) -[e1]-> () ON ''',
'            || graph',
'            || '' WHERE id(x) IN ''',
'            || id_strings;',
'    END IF;',
'    ',
'    SELECT ORA_PGQL_TO_JSON(query) INTO data  FROM sys.dual ;',
'    apex_util.prn(data, false);',
'END;',
''))
,p_process_clob_language=>'PLSQL'
,p_internal_uid=>19321857745465329041
);
wwv_flow_imp_page.create_page_process(
 p_id=>wwv_flow_imp.id(6221466830275)
,p_process_sequence=>20
,p_process_point=>'BEFORE_HEADER'
,p_process_type=>'NATIVE_PLSQL'
,p_process_name=>'Load Saved Searches'
,p_static_id=>'load-saved-searches'
,p_process_sql_clob=>wwv_flow_string.join(wwv_flow_t_varchar2(
'BEGIN',
'    SELECT COALESCE(',
'               JSON_ARRAYAGG(action FORMAT JSON ORDER BY id ASC RETURNING CLOB),',
'               TO_CLOB(''[]'')',
'           )',
'      INTO :P4_SAVED_SEARCHES',
'      FROM EBA_GRAPHVIZ_SAVED_SEARCH',
'     WHERE USER_ID = v(''APP_USER'')',
'       AND JSON_EXISTS(action, ''$.filterRoot'');',
'END;'))
,p_process_clob_language=>'PLSQL'
,p_internal_uid=>2068254545585307746
);
wwv_flow_imp_page.create_page_process(
 p_id=>wwv_flow_imp.id(6329624830274)
,p_process_sequence=>30
,p_process_point=>'ON_DEMAND'
,p_process_type=>'NATIVE_PLSQL'
,p_process_name=>'Update Saved Search'
,p_static_id=>'update-saved-search'
,p_process_sql_clob=>wwv_flow_string.join(wwv_flow_t_varchar2(
'DECLARE',
'    action_type VARCHAR2(100) := JSON_VALUE(apex_application.g_clob_01, ''$.type'');',
'    search_id   VARCHAR2(4000) := JSON_VALUE(apex_application.g_clob_01, ''$.savedSearch.id'');',
'    search_name VARCHAR2(4000) := JSON_VALUE(apex_application.g_clob_01, ''$.savedSearch.name'');',
'    search_data CLOB := JSON_QUERY(apex_application.g_clob_01, ''$.savedSearch'' RETURNING CLOB);',
'BEGIN',
'    IF action_type = ''savedSearch/upsert'' THEN',
'        UPDATE EBA_GRAPHVIZ_SAVED_SEARCH',
'           SET action = search_data',
'         WHERE USER_ID = v(''APP_USER'')',
'           AND JSON_EXISTS(action, ''$.filterRoot'')',
'           AND (JSON_VALUE(action, ''$.id'') = COALESCE(search_id, search_name)',
'                OR JSON_VALUE(action, ''$.name'') = search_name);',
'',
'        IF SQL%ROWCOUNT = 0 THEN',
'            INSERT INTO EBA_GRAPHVIZ_SAVED_SEARCH (ACTION, USER_ID)',
'            VALUES (search_data, v(''APP_USER''));',
'        END IF;',
'    ELSIF action_type = ''savedSearch/delete'' THEN',
'        DELETE FROM EBA_GRAPHVIZ_SAVED_SEARCH',
'         WHERE USER_ID = v(''APP_USER'')',
'           AND JSON_EXISTS(action, ''$.filterRoot'')',
'           AND (JSON_VALUE(action, ''$.id'') = JSON_VALUE(apex_application.g_clob_01, ''$.id'')',
'                OR JSON_VALUE(action, ''$.name'') = JSON_VALUE(apex_application.g_clob_01, ''$.id''));',
'    END IF;',
'',
'    apex_json.open_object;',
'    apex_json.write(''success'', TRUE);',
'    apex_json.close_object;',
'EXCEPTION',
'    WHEN OTHERS THEN',
'        apex_json.open_object;',
'        apex_json.write(''success'', FALSE);',
'        apex_json.write(''severity'', ''error'');',
'        apex_json.write(''message'', SQLERRM);',
'        apex_json.close_object;',
'END;'))
,p_process_clob_language=>'PLSQL'
,p_process_error_message=>'error occurred during saved search update'
,p_internal_uid=>2068254666938307746
);
end;
