wwv_flow_imp_page.create_page_process(
 p_id=>wwv_flow_imp.id(9776217779028)
,p_process_sequence=>20
,p_process_point=>'BEFORE_HEADER'
,p_process_type=>'NATIVE_PLSQL'
,p_process_name=>'Load Exploration Saves'
,p_static_id=>'load-exploration-saves'
,p_process_sql_clob=>wwv_flow_string.join(wwv_flow_t_varchar2(
'BEGIN',
'    SELECT COALESCE(',
'               JSON_ARRAYAGG(action FORMAT JSON ORDER BY id ASC RETURNING CLOB),',
'               TO_CLOB(''[]'')',
'           )',
'      INTO :P8_EXPLORATION_SAVES',
'      FROM EBA_GRAPHVIZ_GRAPH_ACTION',
'     WHERE USER_ID = v(''APP_USER'')',
'       AND JSON_VALUE(action, ''$.id'') IS NOT NULL',
'       AND JSON_VALUE(action, ''$.name'') IS NOT NULL',
'       AND JSON_EXISTS(action, ''$.actions'');',
'END;'))
,p_process_clob_language=>'PLSQL'
,p_internal_uid=>2058242453332740886
);
wwv_flow_imp_page.create_page_process(
 p_id=>wwv_flow_imp.id(9843056779028)
,p_process_sequence=>10
,p_process_point=>'ON_DEMAND'
,p_process_type=>'NATIVE_PLSQL'
,p_process_name=>'Update'
,p_static_id=>'update'
,p_process_sql_clob=>wwv_flow_string.join(wwv_flow_t_varchar2(
'DECLARE',
'    action_type VARCHAR2(100) := JSON_VALUE(apex_application.g_clob_01, ''$.type'');',
'    save_id    VARCHAR2(4000) := JSON_VALUE(apex_application.g_clob_01, ''$.explorationSave.id'');',
'    save_data  CLOB := JSON_QUERY(apex_application.g_clob_01, ''$.explorationSave'' RETURNING CLOB);',
'BEGIN',
'    IF action_type = ''exploration/upsert'' THEN',
'        UPDATE EBA_GRAPHVIZ_GRAPH_ACTION',
'           SET action = save_data',
'         WHERE USER_ID = v(''APP_USER'')',
'           AND JSON_VALUE(action, ''$.id'') = save_id',
'           AND JSON_EXISTS(action, ''$.actions'');',
'',
'        IF SQL%ROWCOUNT = 0 THEN',
'            INSERT INTO EBA_GRAPHVIZ_GRAPH_ACTION (ACTION, USER_ID)',
'            VALUES (save_data, v(''APP_USER''));',
'        END IF;',
'    ELSIF action_type = ''exploration/delete'' THEN',
'        DELETE FROM EBA_GRAPHVIZ_GRAPH_ACTION',
'         WHERE USER_ID = v(''APP_USER'')',
'           AND JSON_VALUE(action, ''$.id'') = JSON_VALUE(apex_application.g_clob_01, ''$.id'')',
'           AND JSON_EXISTS(action, ''$.actions'');',
'    END IF;',
'',
'    apex_json.open_object;',
'    apex_json.write(''success'', TRUE);',
'    apex_json.close_object;',
'END;'))
,p_process_clob_language=>'PLSQL'
,p_process_error_message=>'error occurred during exploration save update'
,p_internal_uid=>11919111980862409
);
end;
