wwv_flow_imp_page.create_page_plug(
 p_id=>wwv_flow_imp.id(1203333436696702)
,p_plug_name=>'Vertex Position Persistence Graph'
,p_static_id=>'vertex-position-graph'
,p_region_name=>'vertex-position-graph'
,p_region_template_options=>'#DEFAULT#:js-showMaximizeButton:t-Region--scrollBody'
,p_plug_template=>4073835273271169698
,p_plug_display_sequence=>30
,p_include_in_reg_disp_sel_yn=>'Y'
,p_plug_item_display_point=>'ABOVE'
,p_query_type=>'SQL'
,p_plug_source=>wwv_flow_string.join(wwv_flow_t_varchar2(
'select ora_pgql_to_json(''',
' SELECT * FROM MATCH (n) -[e]-> (m) ON EBA_SAMPLE_GRAPH'', :PAGE_START, :PAGE_SIZE',
') as query from SYS.DUAL;'))
,p_plug_source_type=>'PLUGIN_GRAPHVIZ'
,p_attributes=>wwv_flow_t_plugin_attributes(wwv_flow_t_varchar2(
  'attribute_05', 'N',
  'attribute_06', '100',
  'attribute_10', 'modes:exploration',
  'attribute_14', 'Y',
  'attribute_15', wwv_flow_string.join(wwv_flow_t_varchar2(
    'let savedPositions = [];',
    'try {',
    '    const positions = JSON.parse(apex.item(''P21_VERTEX_POSITIONS'').getValue() || ''[]'');',
    '    savedPositions = Array.isArray(positions) ? positions : [];',
    '} catch (error) {',
    '    console.error(''Unable to restore saved vertex positions:'', error);',
    '}',
    '',
    'const positionsById = new Map(',
    '    savedPositions.map((position) => [String(position.id), position])',
    ');',
    'vertices.forEach((vertex) => {',
    '    const position = positionsById.get(String(vertex.id));',
    '    if (position) {',
    '        vertex.normalizedPosition = {',
    '            id: vertex.id,',
    '            xRatio: Number(position.xRatio),',
    '            yRatio: Number(position.yRatio)',
    '        };',
    '    }',
    '});')),
  'attribute_16', '640',
  'bind_variable_pgql', 'Y',
  'custom_theme', 'N',
  'darktheme', 'N',
  'default_legend_enabled', 'Y',
  'defaults_for_modes', 'interactionActive:fitToScreenActive:stickyActive',
  'enable_evolution', 'N',
  'enable_expand', 'N',
  'escapehtml', 'N',
  'exploration_options', 'expand:focus:group:ungroup:drop:undo:redo:reset',
  'legend_state', 'expanded',
  'legendwidth', '300',
  'livesearch', 'N',
  'modes_options', 'interaction:fitToScreen:sticky',
  'schema_visualization', 'N',
  'showtitle', 'Y',
  'update', wwv_flow_string.join(wwv_flow_t_varchar2(
    'const positionItem = apex.item(''P21_VERTEX_POSITIONS'');',
    'const readPositions = () => {',
    '    try {',
    '        const positions = JSON.parse(positionItem.getValue() || ''[]'');',
    '        return Array.isArray(positions) ? positions : [];',
    '    } catch (error) {',
    '        console.error(''Unable to read saved vertex positions:'', error);',
    '        return [];',
    '    }',
    '};',
    '',
    'let response;',
    'try {',
    '    response = await apex.server.process(''Update Vertex Position'', {',
    '        p_clob_01: JSON.stringify(action)',
    '    }, {dataType: ''json''});',
    '} catch (error) {',
    '    return {',
    '        success: false,',
    '        severity: ''error'',',
    '        message: error?.responseText || error?.message || String(error)',
    '    };',
    '}',
    '',
    'if (!response || response.success === false) {',
    '    return response;',
    '}',
    '',
    'const positionsById = new Map(',
    '    readPositions().map((position) => [String(position.id), position])',
    ');',
    'if (action.type === ''vertexPosition/upsert'') {',
    '    (action.vertexPositions || []).forEach((position) => {',
    '        positionsById.set(String(position.id), {',
    '            id: String(position.id),',
    '            xRatio: position.xRatio,',
    '            yRatio: position.yRatio',
    '        });',
    '    });',
    '} else if (action.type === ''vertexPosition/delete'') {',
    '    (action.vertexIds || []).forEach((vertexId) => positionsById.delete(String(vertexId)));',
    '}',
    'positionItem.setValue(JSON.stringify([...positionsById.values()]));',
    'return response;')),
  'update_supported_actions', 'vertexPosition/delete:vertexPosition/upsert',
  'visibility_toggle_mode', 'hideWhenAnyUnchecked')).to_clob
,p_updated_on=>wwv_flow_imp.dz('20260914174843Z')
,p_updated_by=>'TEST1'
);
