wwv_flow_imp_page.create_page_plug(
 p_id=>wwv_flow_imp.id(1203830124696719)
,p_plug_name=>'Vertex Position Callback Illustration'
,p_static_id=>'vertex-position-illustration'
,p_region_template_options=>'#DEFAULT#:t-ContentBlock--h3'
,p_plug_template=>2323592004483952560
,p_plug_display_sequence=>20
,p_include_in_reg_disp_sel_yn=>'Y'
,p_plug_item_display_point=>'ABOVE'
,p_location=>null
,p_plug_source=>wwv_flow_string.join(wwv_flow_t_varchar2(
'<p>',
'  This page stores normalized viewport-relative coordinates in the database and',
'  adds them to matching vertices as <code>normalizedPosition</code> when the graph',
'  is loaded again. The plugin''s normalized layout coordinates are preserved',
'  without clamping them to the viewport boundary.',
'</p>',
'',
'<h3>Vertex Position Upsert</h3>',
'<p>',
'  Dragging a vertex while the <strong>Sticky</strong> interaction is enabled invokes',
'  the centralized <code>Update</code> callback with the latest positions:',
'</p>',
'<pre><code>{',
'  "type": "vertexPosition/upsert",',
'  "vertexPositions": [',
'    { "id": 100, "xRatio": 0.42, "yRatio": 0.37 }',
'  ]',
'}</code></pre>',
'',
'<h3>Vertex Position Delete</h3>',
'<p>',
'  Resetting pinned positions invokes the same callback with the vertex IDs whose',
'  stored positions should be removed:',
'</p>',
'<pre><code>{',
'  "type": "vertexPosition/delete",',
'  "vertexIds": [100]',
'}</code></pre>',
'',
'<p>',
'  Drag a vertex, reload the page, and confirm that it returns to the same relative',
'  position. Use <strong>Reset Positions</strong> in the graph toolbar and reload',
'  again to verify that the stored position was deleted.',
'</p>'))
,p_attributes=>wwv_flow_t_plugin_attributes(wwv_flow_t_varchar2(
  'expand_shortcuts', 'N',
  'output_as', 'HTML')).to_clob
);
wwv_flow_imp_page.create_page_item(
 p_id=>wwv_flow_imp.id(1203843762696719)
,p_name=>'P21_VERTEX_POSITIONS'
,p_item_sequence=>5
,p_item_plug_id=>wwv_flow_imp.id(1203333436696702)
,p_source_type=>'ALWAYS_NULL'
,p_display_as=>'NATIVE_HIDDEN'
,p_is_persistent=>'N'
,p_attributes=>wwv_flow_t_plugin_attributes(wwv_flow_t_varchar2(
  'value_protected', 'Y')).to_clob
);
wwv_flow_imp_page.create_page_process(
 p_id=>wwv_flow_imp.id(1204005002696719)
,p_process_sequence=>10
,p_process_point=>'BEFORE_HEADER'
,p_process_type=>'NATIVE_PLSQL'
,p_process_name=>'Load Vertex Positions'
,p_static_id=>'load-vertex-positions'
,p_process_sql_clob=>wwv_flow_string.join(wwv_flow_t_varchar2(
'BEGIN',
'    SELECT COALESCE(',
'               JSON_ARRAYAGG(',
'                   JSON_OBJECT(',
'                       ''id'' VALUE vertex_id,',
'                       ''xRatio'' VALUE x_ratio,',
'                       ''yRatio'' VALUE y_ratio',
'                       RETURNING CLOB',
'                   )',
'                   RETURNING CLOB',
'               ),',
'               TO_CLOB(''[]'')',
'           )',
'      INTO :P21_VERTEX_POSITIONS',
'      FROM EBA_GRAPHVIZ_VERTEX_POSITION',
'     WHERE USER_ID = v(''APP_USER'')',
'       AND GRAPH_NAME = ''EBA_SAMPLE_GRAPH'';',
'END;'))
,p_process_clob_language=>'PLSQL'
,p_internal_uid=>2058242453332740887
);
wwv_flow_imp_page.create_page_process(
 p_id=>wwv_flow_imp.id(1204120880696719)
,p_process_sequence=>10
,p_process_point=>'ON_DEMAND'
,p_process_type=>'NATIVE_PLSQL'
,p_process_name=>'Update Vertex Position'
,p_static_id=>'update-vertex-position'
,p_process_sql_clob=>wwv_flow_string.join(wwv_flow_t_varchar2(
'DECLARE',
'    action_type VARCHAR2(100) := JSON_VALUE(apex_application.g_clob_01, ''$.type'');',
'BEGIN',
'    IF action_type = ''vertexPosition/upsert'' THEN',
'        FOR position IN (',
'            SELECT',
'                vertex_id,',
'                x_ratio,',
'                y_ratio',
'              FROM JSON_TABLE(',
'                  apex_application.g_clob_01,',
'                  ''$.vertexPositions[*]''',
'                  COLUMNS (',
'                      vertex_id VARCHAR2(1000) PATH ''$.id'',',
'                      x_ratio NUMBER PATH ''$.xRatio'',',
'                      y_ratio NUMBER PATH ''$.yRatio''',
'                  )',
'              )',
'        ) LOOP',
'            UPDATE EBA_GRAPHVIZ_VERTEX_POSITION',
'               SET X_RATIO = position.x_ratio,',
'                   Y_RATIO = position.y_ratio',
'             WHERE USER_ID = v(''APP_USER'')',
'               AND GRAPH_NAME = ''EBA_SAMPLE_GRAPH''',
'               AND VERTEX_ID = position.vertex_id;',
'',
'            IF SQL%ROWCOUNT = 0 THEN',
'                INSERT INTO EBA_GRAPHVIZ_VERTEX_POSITION (',
'                    USER_ID,',
'                    GRAPH_NAME,',
'                    VERTEX_ID,',
'                    X_RATIO,',
'                    Y_RATIO',
'                ) VALUES (',
'                    v(''APP_USER''),',
'                    ''EBA_SAMPLE_GRAPH'',',
'                    position.vertex_id,',
'                    position.x_ratio,',
'                    position.y_ratio',
'                );',
'            END IF;',
'        END LOOP;',
'    ELSIF action_type = ''vertexPosition/delete'' THEN',
'        DELETE FROM EBA_GRAPHVIZ_VERTEX_POSITION',
'         WHERE USER_ID = v(''APP_USER'')',
'           AND GRAPH_NAME = ''EBA_SAMPLE_GRAPH''',
'           AND VERTEX_ID IN (',
'               SELECT vertex_id',
'                 FROM JSON_TABLE(',
'                     apex_application.g_clob_01,',
'                     ''$.vertexIds[*]''',
'                     COLUMNS (',
'                         vertex_id VARCHAR2(1000) PATH ''$''',
'                     )',
'                 )',
'           );',
'    END IF;',
'',
'    apex_json.open_object;',
'    apex_json.write(''success'', TRUE);',
'    apex_json.close_object;',
'EXCEPTION',
'    WHEN OTHERS THEN',
'        apex_json.open_object;',
'        apex_json.write(''success'', FALSE);',
'        apex_json.write(''severity'', ''error'');',
'        apex_json.write(''message'', SQLERRM);',
'        apex_json.close_object;',
'END;'))
,p_process_clob_language=>'PLSQL'
,p_process_error_message=>'error occurred during vertex position update'
,p_internal_uid=>11919111980862410
);
end;
